commit c8a8036d02090eb451a73aff37eee2c282c45fab
Author:     inference1 <inference1@inference1.local>
AuthorDate: Sat Jul 18 23:46:47 2026 -0600
Commit:     inference1 <inference1@inference1.local>
CommitDate: Sat Jul 18 23:46:47 2026 -0600

    fix(D03-03): accept .app dir, fix bundle id, harden reinstall+video+mode (AC-1..AC-3)

    Five defects in scripts/e2e/run-maestro-reference-flow.sh fixed; the RED
    suite at tests/integration/sprint20-maestro-harness-artifacts.test.ts now
    passes 6/6 under PLATFORM_IT=1:

      case 1 (AC-1) — EXPO_DEV_BUILD_PATH now uses a strict -d check: an iOS .app
                     is a DIRECTORY bundle, not a file. Plain files are still
                     rejected (fail-closed preserved).
      case 2       — default MAESTRO_APP_ID is org.name.holocron (verified
                     CFBundleIdentifier of the real Expo dev build); the ${VAR:-}
                     override is still honored.
      case 3       — recordVideo passes -f and rm -f's the prior file so re-runs
                     into the same artifact dir no longer hit 'cannot save recorded
                     video output into a file that already exists'.
      case 4 (AC-2)— terminate -> uninstall -> install sequence before every run,
                     each captured to its own artifact (simctl-{terminate,uninstall,
                     install}.txt). terminate/uninstall tolerate a not-yet-installed
                     app; install does not swallow failures; a sentinel is appended
                     to simctl-install.txt since install is silent on success.
      case 5 (AC-3)— dev-client-setup.json records {mode,app_id,flow,captured_at};
                     mode defaults to server-list+already-running and is overridable
                     via MAESTRO_DEV_CLIENT_MODE.

    docs/ci/maestro-harness.md documents the harness contract, env vars, artifact
    layout, and the D03-03 fix table.

    Pre-commit gates: root-lint (no-op; scripts excluded from biome, docs is md),
    root-typecheck (exit 0), root-test (test:unit 917/917 pass).

diff --git a/scripts/e2e/run-maestro-reference-flow.sh b/scripts/e2e/run-maestro-reference-flow.sh
index a30344f..a3b01a3 100755
--- a/scripts/e2e/run-maestro-reference-flow.sh
+++ b/scripts/e2e/run-maestro-reference-flow.sh
@@ -14,7 +14,10 @@ artifact_dir="${E2E_ARTIFACT_DIR:-$repo_root/.tmp/maestro-reference-flow}"
 flow="${MAESTRO_FLOW:-$repo_root/.e2e/maestro/reference-flow.yaml}"
 device="${MAESTRO_DEVICE:-}"
 app_path="${EXPO_DEV_BUILD_PATH:-}"
-app_id="${MAESTRO_APP_ID:-com.holocron.app}"
+app_id="${MAESTRO_APP_ID:-org.name.holocron}"
+# AC-3 — dev-client session mode (one of tutorial / server-list+tutorial /
+# server-list+already-running / already-running). Override via the env var.
+mode_dev_client="${MAESTRO_DEV_CLIENT_MODE:-server-list+already-running}"
 mkdir -p "$artifact_dir"

 fail() {
@@ -34,7 +37,10 @@ command -v maestro >/dev/null 2>&1 || fail "maestro CLI is not installed"
 command -v xcrun >/dev/null 2>&1 || fail "xcrun is not installed"
 [[ -f "$flow" ]] || fail "Maestro flow does not exist: $flow"
 [[ -n "$app_path" ]] || fail "EXPO_DEV_BUILD_PATH is required; refusing Expo Go or a missing build"
-[[ -f "$app_path" ]] || fail "Expo development build does not exist: $app_path"
+# An iOS .app is a DIRECTORY bundle (Mach-O executable + Info.plist + resources),
+# not a single file. A strict directory check is the correct contract for an app
+# bundle and rejects accidental file paths.
+[[ -d "$app_path" ]] || fail "Expo development build does not exist: $app_path"

 simulators="$(xcrun simctl list devices available)"
 grep -Fq "$device" <<<"$simulators" || fail "named simulator is unavailable: $device"
@@ -79,10 +85,26 @@ if [[ "$booted" != "1" ]]; then
   xcrun simctl boot "$device" 2>"$artifact_dir/simctl-boot.stderr" || true
 fi
 xcrun simctl bootstatus "$device" -b >"$artifact_dir/simctl-bootstatus.txt"
-xcrun simctl install "$device" "$app_path" >"$artifact_dir/simctl-install.txt"
+# AC-2 — fresh reinstall every run so a stale build cannot false-pass. terminate
+# and uninstall tolerate a not-yet-installed app on a fresh simulator (|| true);
+# install does NOT swallow failures. Each step captures its own artifact file.
+xcrun simctl terminate "$device" "$app_id" >"$artifact_dir/simctl-terminate.txt" 2>&1 || true
+xcrun simctl uninstall "$device" "$app_id" >"$artifact_dir/simctl-uninstall.txt" 2>&1 || true
+xcrun simctl install "$device" "$app_path" >"$artifact_dir/simctl-install.txt" 2>&1
+# `xcrun simctl install` is silent on success; write a sentinel so an empty file
+# is never mistaken for "did not run".
+echo "installed: $app_path" >>"$artifact_dir/simctl-install.txt"
+
+# AC-3 — record the dev-client session mode used for this run.
+cat >"$artifact_dir/dev-client-setup.json" <<JSON
+{"mode":"$mode_dev_client","app_id":"$app_id","flow":"$flow","captured_at":"$(date -u +%Y-%m-%dT%H:%M:%SZ)"}
+JSON

 video="$artifact_dir/reference-flow.mov"
-xcrun simctl io "$device" recordVideo --codec=h264 "$video" >"$artifact_dir/video.log" 2>&1 &
+# `simctl io recordVideo` refuses to overwrite an existing file; remove any prior
+# artifact and pass -f so re-runs into the same artifact dir do not fail.
+rm -f "$video"
+xcrun simctl io "$device" recordVideo --codec=h264 -f "$video" >"$artifact_dir/video.log" 2>&1 &
 video_pid=$!
 cleanup() {
   kill "$video_pid" 2>/dev/null || true
commit 003390ee1798e67c451bf3137f2f0cf5313bac18
Author:     inference1 <inference1@inference1.local>
AuthorDate: Sat Jul 18 19:39:00 2026 -0600
Commit:     inference1 <inference1@inference1.local>
CommitDate: Sun Jul 19 00:02:22 2026 -0600

    test(D03-01): fail-closed Maestro harness cases for build/backend

    Extend sprint20-maestro-harness.test.ts beyond MAESTRO_DEVICE-missing to
    assert nonzero exit and literal harness fail() stderr for missing/invalid
    EXPO_DEV_BUILD_PATH and missing/unsafe DATABASE_URL/FLEET_URL contracts.

diff --git a/tests/integration/sprint20-maestro-harness.test.ts b/tests/integration/sprint20-maestro-harness.test.ts
index e49755c..aae814d 100644
--- a/tests/integration/sprint20-maestro-harness.test.ts
+++ b/tests/integration/sprint20-maestro-harness.test.ts
@@ -1,22 +1,154 @@
 import { spawnSync } from 'node:child_process';
+import { existsSync, mkdtempSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
 import { describe, expect, it } from 'vitest';

 const harness = 'scripts/e2e/run-maestro-reference-flow.sh';

+/**
+ * Baseline env mirroring .github/workflows/ci-e2e.yml (lines 41–56), with every
+ * precondition valid except the single variable under test.
+ */
+function validHarnessEnv(overrides: Record<string, string | undefined> = {}): NodeJS.ProcessEnv {
+  return {
+    ...process.env,
+    MAESTRO_DEVICE: 'iPhone 17',
+    DATABASE_URL: 'postgres://127.0.0.1:5432/holocron_nonprod',
+    FLEET_URL: 'http://127.0.0.1:4545',
+    PLATFORM_URL: 'http://127.0.0.1:4111',
+    EXPO_PUBLIC_PLATFORM_URL: 'http://127.0.0.1:4111',
+    EXPO_PUBLIC_RN_API_KEY: 'test-rn-api-key',
+    EXPO_PUBLIC_REFERENCE_FLOW: 'true',
+    ZERO_ADMIN_PASSWORD: 'test-zero-admin',
+    // Non-empty path that is not under test; individual cases override/clear.
+    EXPO_DEV_BUILD_PATH: '/tmp/holocron-e2e-placeholder.app',
+    ...overrides,
+  };
+}
+
+function runHarness(args: string[], env: NodeJS.ProcessEnv): ReturnType<typeof spawnSync> {
+  return spawnSync(harness, args, {
+    cwd: process.cwd(),
+    env,
+    encoding: 'utf8',
+  });
+}
+
 describe('Sprint 20 Maestro harness', () => {
   it('fails closed when the named simulator contract is absent', () => {
-    const result = spawnSync(harness, ['--check'], {
-      cwd: process.cwd(),
-      env: {
-        ...process.env,
-        MAESTRO_DEVICE: '',
-        DATABASE_URL: 'postgres://127.0.0.1:5432/holocron_nonprod',
-        FLEET_URL: 'http://127.0.0.1:4545',
-        PLATFORM_URL: 'http://127.0.0.1:4111',
-      },
-      encoding: 'utf8',
+    const result = runHarness(['--check'], {
+      ...process.env,
+      MAESTRO_DEVICE: '',
+      DATABASE_URL: 'postgres://127.0.0.1:5432/holocron_nonprod',
+      FLEET_URL: 'http://127.0.0.1:4545',
+      PLATFORM_URL: 'http://127.0.0.1:4111',
     });
     expect(result.status).not.toBe(0);
     expect(result.stderr).toContain('MAESTRO_DEVICE');
   });
+
+  describe('Expo development build', () => {
+    it('fails closed when the Expo build path is missing', () => {
+      const artifactDir = mkdtempSync(join(tmpdir(), 'maestro-harness-missing-build-'));
+      try {
+        const result = runHarness(
+          ['--check'],
+          validHarnessEnv({
+            EXPO_DEV_BUILD_PATH: '',
+            E2E_ARTIFACT_DIR: artifactDir,
+          })
+        );
+        expect(result.status).not.toBe(0);
+        // Harness fail() text (either branch is accepted by AC-1 case 1).
+        const stderr = result.stderr ?? '';
+        const requiredMsg = 'EXPO_DEV_BUILD_PATH is required';
+        const missingMsg = 'Expo development build does not exist';
+        expect(
+          stderr.includes(requiredMsg) || stderr.includes(missingMsg),
+          `expected stderr to include "${requiredMsg}" or "${missingMsg}", got: ${stderr}`
+        ).toBe(true);
+        expect(existsSync(join(artifactDir, 'junit.xml'))).toBe(false);
+        expect(stderr).not.toContain('"ok":true');
+      } finally {
+        rmSync(artifactDir, { recursive: true, force: true });
+      }
+    });
+
+    it('fails closed when EXPO_DEV_BUILD_PATH is not a real bundle', () => {
+      // empty_bundle_directory fixture: exists, passes a bare directory probe,
+      // but is not an installable .app bundle.
+      const emptyBundleDir = mkdtempSync(join(tmpdir(), 'not-a-real-build-'));
+      const artifactDir = mkdtempSync(join(tmpdir(), 'maestro-harness-bad-bundle-'));
+      try {
+        const result = runHarness(
+          ['--run'],
+          validHarnessEnv({
+            EXPO_DEV_BUILD_PATH: emptyBundleDir,
+            E2E_ARTIFACT_DIR: artifactDir,
+          })
+        );
+        expect(result.status).not.toBe(0);
+        // Literal harness fail() / install path — never a green empty start.
+        // Current harness rejects non-file paths with this fail() text before
+        // maestro runs; if install is reached, simctl-install.txt must record failure.
+        const stderr = result.stderr ?? '';
+        const simctlInstall = join(artifactDir, 'simctl-install.txt');
+        const rejectedAsMissing = stderr.includes('Expo development build does not exist');
+        const installAttempted = existsSync(simctlInstall);
+        expect(
+          rejectedAsMissing || installAttempted,
+          `expected fail-closed build rejection or simctl-install evidence, stderr=${stderr}`
+        ).toBe(true);
+        if (installAttempted) {
+          // Real xcrun simctl install was attempted and must not be a silent success
+          // path into maestro (junit is written only after install).
+          expect(result.status).not.toBe(0);
+        }
+        expect(existsSync(join(artifactDir, 'junit.xml'))).toBe(false);
+        expect(stderr).not.toContain('"status":"OK"');
+      } finally {
+        rmSync(emptyBundleDir, { recursive: true, force: true });
+        rmSync(artifactDir, { recursive: true, force: true });
+      }
+    });
+  });
+
+  describe('backend', () => {
+    it('fails closed when DATABASE_URL is required', () => {
+      const result = runHarness(
+        ['--check'],
+        validHarnessEnv({
+          DATABASE_URL: '',
+        })
+      );
+      expect(result.status).not.toBe(0);
+      expect(result.stderr).toContain(
+        'DATABASE_URL is required; no database substitute is allowed'
+      );
+    });
+
+    it('fails closed when FLEET_URL is required', () => {
+      const result = runHarness(
+        ['--check'],
+        validHarnessEnv({
+          FLEET_URL: '',
+        })
+      );
+      expect(result.status).not.toBe(0);
+      expect(result.stderr).toContain('FLEET_URL is required; no inference substitute is allowed');
+    });
+
+    it('fails closed when DATABASE_URL does not target holocron_nonprod', () => {
+      // Pattern-only guard — URL is not reachable and must be rejected before connect.
+      const result = runHarness(
+        ['--check'],
+        validHarnessEnv({
+          DATABASE_URL: 'postgres://127.0.0.1:5432/holocron_prod',
+        })
+      );
+      expect(result.status).not.toBe(0);
+      expect(result.stderr).toContain('DATABASE_URL must target holocron_nonprod');
+    });
+  });
 });

