text:
  1	/**
  2	 * D03-03 — Maestro reference-flow harness artifact & defect contract.
  3	 *
  4	 * RED-first TDD for five real defects in `scripts/e2e/run-maestro-reference-flow.sh`:
  5	 *   1. `-f` rejects `.app` directory bundles (iOS `.app` is a directory, not a file)
  6	 *   2. Wrong default bundle id (`com.holocron.app` → must be `org.name.holocron`)
  7	 *   3. `recordVideo` fails when the target file already exists (missing `-f`)
  8	 *   4. No terminate/uninstall before install — stale build can false-pass (AC-2)
  9	 *   5. No `dev-client-setup.json` with a `mode` field (AC-3)
 10	 *
 11	 * Gated on PLATFORM_IT=1 (same posture as fail-closed-harness.test.ts) because case 1
 12	 * drives the real script via `xcrun simctl` and a real available simulator UDID.
 13	 *
 14	 *   PLATFORM_IT=1 pnpm vitest run tests/integration/sprint20-maestro-harness-artifacts.test.ts
 15	 */
 16	import { spawnSync } from 'node:child_process';
 17	import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
 18	import { tmpdir } from 'node:os';
 19	import { dirname, join, resolve } from 'node:path';
 20	import { fileURLToPath } from 'node:url';
 21	import { beforeAll, describe, expect, it } from 'vitest';
 22	
 23	const PLATFORM_IT = process.env.PLATFORM_IT === '1';
 24	
 25	const __dirname = dirname(fileURLToPath(import.meta.url));
 26	const REPO_ROOT = resolve(__dirname, '..', '..');
 27	const HARNESS = join(REPO_ROOT, 'scripts', 'e2e', 'run-maestro-reference-flow.sh');
 28	
 29	function readHarness(): string {
 30	  return readFileSync(HARNESS, 'utf8');
 31	}
 32	
 33	/** Discover any available iOS Simulator UDID via `xcrun simctl list`. */
 34	function discoverSimulatorUdid(): string {
 35	  const res = spawnSync('xcrun', ['simctl', 'list', 'devices', 'available'], {
 36	    encoding: 'utf8',
 37	    timeout: 10_000,
 38	  });
 39	  if (res.status !== 0 || !res.stdout) {
 40	    throw new Error(`xcrun simctl list failed (status=${res.status}): ${res.stderr}`);
 41	  }
 42	  const match = res.stdout.match(/[0-9A-F]{8}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{12}/i);
 43	  if (!match) {
 44	    throw new Error('no available iOS Simulator UDID found via xcrun simctl list');
 45	  }
 46	  return match[0];
 47	}
 48	
 49	describe('D03-03 Maestro harness artifact & defect contract', () => {
 50	  beforeAll(() => {
 51	    if (!PLATFORM_IT) {
 52	      throw new Error(
 53	        'PLATFORM_IT=1 required for D03-03 Maestro harness artifact lane — refusing skip-to-green'
 54	      );
 55	    }
 56	  });
 57	
 58	  describe('case 1 — accept .app directory bundle (defect 1, AC-1)', () => {
 59	    it('invoking the harness against a real .app DIRECTORY does not fail with "Expo development build does not exist"', () => {
 60	      const tmpRoot = mkdtempSync(join(tmpdir(), 'd0303-appdir-'));
 61	      // An iOS .app is a DIRECTORY bundle, not a file. The harness must accept a dir.
 62	      const appBundleDir = join(tmpRoot, 'Fake.app');
 63	      mkdirSync(appBundleDir, { recursive: true });
 64	      try {
 65	        const udid = discoverSimulatorUdid();
 66	        const result = spawnSync('bash', [HARNESS, '--check'], {
 67	          cwd: REPO_ROOT,
 68	          env: {
 69	            ...process.env,
 70	            MAESTRO_DEVICE: udid,
 71	            EXPO_DEV_BUILD_PATH: appBundleDir,
 72	            DATABASE_URL: 'postgres://127.0.0.1:5432/holocron_nonprod',
 73	            FLEET_URL: 'http://127.0.0.1:4545',
 74	            PLATFORM_URL: 'http://127.0.0.1:4111',
 75	            EXPO_PUBLIC_RN_API_KEY: 'placeholder-presence-check-key',
 76	            ZERO_ADMIN_PASSWORD: 'placeholder-presence-check-pw',
 77	            // ensure no stale override
 78	            MAESTRO_APP_ID: '',
 79	          },
 80	          encoding: 'utf8',
 81	          timeout: 30_000,
 82	        });
 83	
 84	        // The bug (`-f` on a directory) emits exactly this message and exits 1.
 85	        // The fix (`-d`) passes the app_path gate; --check then succeeds (exit 0)
 86	        // because every prior precondition is a presence/string check satisfied
 87	        // by the placeholders above, and the device UDID is real & available.
 88	        expect(result.stderr).not.toContain('Expo development build does not exist');
 89	        expect(result.status).toBe(0);
 90	        // --check success prints a JSON contract line naming the app path.
 91	        expect(result.stdout).toContain('"ok":true');
 92	        expect(result.stdout).toContain(appBundleDir);
 93	      } finally {
 94	        rmSync(tmpRoot, { recursive: true, force: true });
 95	      }
 96	    });
 97	  });
 98	
 99	  describe('case 2 — default bundle id is org.name.holocron (defect 2)', () => {
100	    it('resolves MAESTRO_APP_ID default to org.name.holocron (the real Expo dev build CFBundleIdentifier)', () => {
101	      const src = readHarness();
102	      // The default-resolution expression must use the verified bundle id.
103	      expect(src).toMatch(/MAESTRO_APP_ID:-org\.name\.holocron/);
104	      // The stale/wrong default must not be the resolved default.
105	      expect(src).not.toMatch(/MAESTRO_APP_ID:-com\.holocron\.app/);
106	    });
107	  });
108	
109	  describe('case 3 — recordVideo uses -f to overwrite (defect 3)', () => {
110	    it('invokes xcrun simctl io recordVideo with --codec=h264 -f so a prior video file is overwritten', () => {
111	      const src = readHarness();
112	      expect(src).toMatch(/simctl io .* recordVideo --codec=h264 -f /);
113	    });
114	  });
115	
116	  describe('case 4 — terminate/uninstall before install (defect 4, AC-2)', () => {
117	    it('runs simctl terminate, then uninstall, then install — each captured to its own artifact', () => {
118	      const src = readHarness();
119	      // All three verbs must be present.
120	      expect(src).toMatch(/simctl terminate "\$device" "\$app_id"/);
121	      expect(src).toMatch(/simctl uninstall "\$device" "\$app_id"/);
122	      expect(src).toMatch(/simctl install "\$device" "\$app_path"/);
123	      // Ordering: terminate before uninstall before install.
124	      const terminateIdx = src.indexOf('simctl terminate');
